export function exportReadTheListMarkdown() {
  const out = [];
  out.push("# READ_THE_LIST — yume-develop AI起動ショートリスト");
  out.push("");
  out.push("> Generated from `runAndReadMe.aiDoc.yume.js`. Do not edit this Markdown directly.");
  out.push("");
  out.push("このファイルは短い入口です。正式な運用ルールの REAL は `runAndReadMe.aiDoc.yume.js` です。");
  out.push("");
  out.push("## まず理解すること");
  out.push("");
  out.push("- `.yume.js` は current HEAD と append-only history を同じ JS ファイルに持つ portable Block file。");
  out.push("- 通常編集は HEAD のみ。`__block.versions` は手で触らず、`commit` で履歴化する。");
  out.push("- Markdown は原則 SHADOW。対応する `.aiDoc.yume.js` がある場合は REAL 側を更新して生成する。");
  out.push("- runtime handler (`runtimes/ver*.handle.yume.js`) は `.yume.js` 名だが `__block` を持たない plain ESM の例外。");
  out.push("- `yume-develop` は本体開発用。サンプルアプリや実験プロジェクトはこの中に作らず、外部の `/Users/AoyamaRito/PJs/sample/` などへ置く。");
  out.push("");
  out.push("## 最初に読むファイル");
  out.push("");
  out.push("```sh");
  out.push("sed -n '1,220p' BIBLE.md");
  out.push("sed -n '1,240p' runYume.js");
  out.push("node runYume.js runAndReadMe.aiDoc.yume.js show head --raw");
  out.push("node runYume.js cli.module.yume.js show head --raw");
  out.push("```");
  out.push("");
  out.push("## Sniper Reading");
  out.push("");
  out.push("`.yume.js` は履歴を含むため、必要になるまで丸ごと読まない。HEAD だけを取る。");
  out.push("");
  out.push("```sh");
  out.push("node runYume.js <file>.yume.js show head --raw");
  out.push("```");
  out.push("");
  out.push("## 作業別に追加で読むもの");
  out.push("");
  out.push("| 作業 | 追加ファイル |");
  out.push("|---|---|");
  out.push("| エンジン | `core.module.yume.js` HEAD |");
  out.push("| CLI | `cli.module.yume.js` HEAD |");
  out.push("| ランタイム | `runtimes/ver002.handle.yume.js` |");
  out.push("| 形式仕様 | `BLOCKFILE.aiDoc.yume.js` HEAD |");
  out.push("| ランタイム仕様 | `runtime.spec.yume.js` HEAD |");
  out.push("| 主要テスト | `e2e.js` |");
  out.push("");
  out.push("## よく使うコマンド");
  out.push("");
  out.push("```sh");
  out.push("# HEAD だけ読む");
  out.push("node runYume.js <file>.yume.js show head --raw");
  out.push("");
  out.push("# touched yume file を検証");
  out.push("node runYume.js <file>.yume.js validate");
  out.push("");
  out.push("# HEAD 変更を履歴化");
  out.push("node runYume.js <file>.yume.js commit --note \"why this change exists\"");
  out.push("");
  out.push("# repository graph check");
  out.push("npm run refs-check");
  out.push("");
  out.push("# full local suite");
  out.push("npm test");
  out.push("");
  out.push("# full repository verification");
  out.push("npm run verify");
  out.push("```");
  out.push("");
  out.push("## 完了条件");
  out.push("");
  for (const criterion of RunAndReadMe.doneCriteria) out.push(`- ${criterion}`);
  out.push("");
  out.push("## 重いので後回しにするもの");
  out.push("");
  out.push("- `BLOCKFILE.aiDoc.yume.js`: 正確な形式仕様が必要なときだけ読む。");
  out.push("- `bible.aiDoc.yume.js`: `BIBLE.md` で足りないときだけ読む。");
  out.push("- `coverage.verify.yume.js`: coverage 作業時だけ読む。");
  out.push("- 外部サンプル (`/Users/AoyamaRito/PJs/sample/`): yume-develop 本体作業では読まない。");
  out.push("");
  out.push("## 報告形式");
  out.push("");
  out.push("変更内容、検証結果、残リスクを短く報告する。");
  out.push("");
  return out.join("\n");
}

